/* @lc app=leetcode id=1594 lang=kotlin */ class Solution { fun maxProductPath(grid: Array<IntArray>): Int = Array(grid.size) { Array(grid[0].size) { 0L to 0L } }.also { dp -> grid.indices.forEach { i -> grid[0].indices.forEach { j -> dp[i][j] = (if (i == 0 && j == 0) listOf(grid[0][0].toLong()) else listOfNotNull(dp.getOrNull(i - 1)?.get(j), dp[i].getOrNull(j - 1)).flatMap { (a, b) -> listOf(a * grid[i][j], b * grid[i][j]) }).let { it.max() to it.min() } } } }.last().last().first.let { if (it < 0) -1 else (it % 1_000_000_007).toInt() } }